WITH with_last AS (SELECT s.id, s.device, s.browser, s.started_at, s.country, top1.event_type, top1.web_event_duration_sec FROM sessions s LEFT JOIN LATERAL (SELECT c.event_type, c.duration_sec AS web_event_duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE), latest_match AS (SELECT s.*, latest.web_event_page, latest.web_event_event_time FROM with_last s LEFT JOIN LATERAL (SELECT c.page AS web_event_page, c.event_time AS web_event_event_time FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), started_at) AS days_since_started_at FROM latest_match WHERE started_at > DATE '2023-04-14' AND web_event_page IS NOT NULL), kept AS (SELECT s.* FROM cleaned s WHERE EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_time <= s.started_at)), latest AS (SELECT *, RANK() OVER (PARTITION BY browser, device ORDER BY web_event_duration_sec DESC NULLS LAST) AS dedup_rank FROM kept QUALIFY dedup_rank = 1), enriched AS (SELECT *, AVG(days_since_started_at) OVER (PARTITION BY event_type ORDER BY days_since_started_at, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS days_since_started_at_avg_5, LEAD(web_event_duration_sec, 2) OVER (PARTITION BY web_event_page ORDER BY dedup_rank, id) AS next_web_event_duration_sec FROM latest WHERE event_type = 'add_to_cart'), flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY web_event_page ORDER BY started_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM enriched), sessions_sessions AS (SELECT id, browser, started_at, country, event_type, web_event_duration_sec, web_event_page, web_event_event_time, days_since_started_at, dedup_rank, days_since_started_at_avg_5, next_web_event_duration_sec, SUM(is_new_session) OVER (PARTITION BY web_event_page ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT session_no, CASE WHEN days_since_started_at >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END AS days_since_started_at_tier, ROUND(AVG(days_since_started_at), 2) AS avg_days_since_started_at, MIN(web_event_event_time) AS first_seen, PERCENTILE_APPROX(days_since_started_at, 0.9) AS days_since_started_at_p90 FROM sessions_sessions GROUP BY GROUPING SETS ((session_no, CASE WHEN days_since_started_at >= 76 THEN 'PREMIUM' ELSE 'STANDARD' END), (session_no), ()) HAVING PERCENTILE_APPROX(days_since_started_at, 0.9) >= 0;
